import { CHEATS } from '../src/engine/cheats/registry';
import { CHEAT_GROUPS } from '../src/engine/cheats/types';

export const START =
  '<!-- cheats:start (generated by npm run docs:cheats; do not edit by hand) -->';
export const END = '<!-- cheats:end -->';

/** The README cheat list, generated from the registry so it can't drift. */
export function cheatMarkdown(): string {
  const out: string[] = [START, ''];
  for (const g of CHEAT_GROUPS) {
    const defs = CHEATS.filter((c) => c.group === g.id);
    if (!defs.length) continue;
    out.push(`### ${g.label}`, '', '| Console | What it does |', '|---|---|');
    for (const c of defs) out.push(`| \`${c.syntax}\` | ${c.help.replace(/\|/g, '\\|')} |`);
    out.push('');
  }
  out.push(
    `${CHEATS.length} commands in all. Every one is also a form in the cheat panel.`,
    '',
    END,
  );
  return out.join('\n');
}
